VALUES ('NIH SBIR/STTR (Parent SBIR PA-27-100 / Parent STTR PA-27-102)', 'NIH, CDC and FDA Parent SBIR (R43/R44, PA-27-100) and NIH Parent STTR (R41/R42, PA-27-102), released May 28, 2026 and expiring Apr 6, 2027, for US small businesses developing health/biotech innovations. Standard due dates are Sep 5, Jan 5 and Apr 5 — the Sep 2026 date has passed, so the next standard due date is Jan 5, 2027 at 5:00 p.m. applicant local time; Fast-Track and Direct to Phase II are also accepted under PA-27-100.', 'government_grant', 'physical', '9000 Rockville Pike, Bethesda, MD 20892', 'Bethesda', 'United States', 39.00403, -77.09928, 'https://seed.nih.gov/small-business-funding/find-funding/sbir-sttr-funding-opportunities', 'SEEDinfo@nih.gov', true, false, ARRAY['research','mvp','validation']::text[],
 'Phase I SBA guideline up to $323,090 total costs, with participating Institutes offering waiver ceilings of up to $400,000 or $700,000 per Phase I depending on institute (Phase II guideline up to $2,153,927, waivers up to $3,000,000)', 700000, '2027-01-05T23:59:59-04:00', false, 'open', NULL, NULL,
 ARRAY['US small business concern','500 employees or fewer','for-profit','STTR requires nonprofit research partner']::text[], ARRAY['health','biotech','life sciences','medical devices','digital health']::text[], ARRAY['small_business']::text[], '{}', false, false, NULL, 'https://seed.nih.gov/small-business-funding/find-funding/sbir-sttr-funding-opportunities', '2026-10-27T00:00:00-04:00')
