 ARRAY['US-Israel company pair','two unrelated companies','joint application','commercial potential']::text[], ARRAY['software','AI','semiconductors','life sciences','cybersecurity','energy','agtech','fintech','healthcare IT']::text[], ARRAY['company']::text[], '{}', false, true, NULL, 'https://www.birdf.com/bird_programs/bird-general-program/', '2026-10-27T00:00:00-04:00')
