VALUES ('The Pollination Project — Daily Seed Grants', 'Rolling seed grants for grassroots changemakers, verified on the official apply page: applications are accepted on a rolling basis (brief year-end closure), received before month-end and reviewed the following month. NOTE the current Daily Grant amount is $500 (reduced from $1,000). Strict eligibility: volunteer-led projects with NO paid staff, total project budget under $10,000 and organizational budget under $50,000, serving charitable purposes (not personal gain or a for-profit business) — a fit for social-impact and nonprofit projects in the journey, not for a paid-staff for-profit startup itself. Free to apply.', 'government_grant', 'online', 'Brevard, North Carolina, USA', 'Brevard', 'United States', 35.2334, -82.7343, 'https://thepollinationproject.org/apply/', NULL, true, false, ARRAY['idea','validation']::text[],
 '$500 seed grant (current amount; previously $1,000)', 500, NULL, true, 'open', NULL, NULL,
 ARRAY['social_impact','volunteer_led','no_paid_staff','org_budget_under_50000','project_budget_under_10000','charitable_purpose','free_to_apply']::text[], ARRAY['social_impact','environment','education','health']::text[], ARRAY['individual_group_or_early_nonprofit']::text[], '{}', false, false, NULL, 'https://thepollinationproject.org/apply/', '2026-10-27T00:00:00-04:00')
