VALUES ('Boundless Futures Foundation — EmpowHer Grant', 'Equity-free grants for US female founders (age 22+) whose revenue-earning businesses are up to five years old and put social impact front and center — poverty, hunger and humanitarian aid, sustainability and the environment, or strong communities — paid as reimbursement against documented business expenses, plus access to an Advisory Circle of seasoned female founders. The foundation announced (Sep 17, 2026) that the next EmpowHer round opens for application on November 1, 2026; the closing date for that round has not yet been published. Free to apply; a background check is part of the process.', 'government_grant', 'online', 'Traverse City, Michigan, USA', 'Traverse City', 'United States', 44.7631, -85.6206, 'https://boundlessfutures.org/our-impact', NULL, true, false, ARRAY['validation','launch','growth']::text[],
 'Up to $50,000 (latest round awarded $50,000 per recipient), paid as reimbursement against documented business expenses', 50000, NULL, false, 'opening_soon', NULL, NULL,
 ARRAY['women_founders','female_founded','social_impact','revenue_required','us_based','free_to_apply']::text[], ARRAY['all','sustainability','social_impact']::text[], ARRAY['small_business']::text[], '{}', true, false, NULL, 'https://boundlessfutures.org/our-impact', '2026-10-27T00:00:00-04:00')
